const entrada = $input.first()?.json ?? {};

const system = typeof entrada.MSG_Prompt_System === 'string'
  ? entrada.MSG_Prompt_System.trim()
  : '';

const user = typeof entrada.MSG_Prompt_User === 'string'
  ? entrada.MSG_Prompt_User.trim()
  : '';

if (!system || !user) {
  throw new Error(
    'CORE Cloudflare: MSG_Prompt_System e MSG_Prompt_User são obrigatórios.'
  );
}

return [
  {
    json: {
      _route: 'request',
      contexto: {
        modelo: '@cf/meta/llama-3.3-70b-instruct-fp8-fast',

        request_body: {
          messages: [
            {
              role: 'system',
              content: system
            },
            {
              role: 'user',
              content: user
            }
          ],
          max_tokens: 1024,
          stream: false
        },

        _core: {
          tentativa: 1,
          max_tentativas: 3
        }
      }
    }
  }
];

// Use o contexto da API selecionada nesta tentativa. O fallback mantém uma
// mensagem de erro útil caso a execução pare antes da consulta à SP.
let context;
try {
  context = $('Preparar Conta Cloudflare').last().json.contexto;
} catch {
  context = $('Validar e Preparar').first().json.contexto;
}
if (!context) {
  throw new Error('CORE Cloudflare: contexto da requisição não encontrado.');
}

// Normaliza a resposta completa do HTTP Request.
const response = $json ?? {};
const status = Number(response.statusCode ?? 0);
const body = response.body ?? response;
const result = body?.result;
const text = typeof result?.response === 'string' ? result.response.trim() : '';

// Sucesso: o Workers AI devolveu texto.
if (status >= 200 && status < 300 && body?.success !== false && text) {
  return [{
    json: {
      _route: 'success',
      contexto: context,
      text,
      usage: result?.usage ?? null,
      status_code: status,
    },
  }];
}

// Extrai código e mensagem fornecidos pela Cloudflare.
const providerError = Array.isArray(body?.errors) ? body.errors[0] : body?.error;
const providerCode = Number(providerError?.code ?? 0);

// Classifica falhas para diagnóstico e política de repetição.
let code = 'API_ERROR';
if (status === 401) code = 'AUTHENTICATION_FAILED';
else if (status === 403) code = 'AUTHORIZATION_FAILED';
else if (status === 429 && providerCode === 4006) code = 'DAILY_NEURON_QUOTA_EXHAUSTED';
else if (status === 429) code = 'LIMIT_EXCEEDED';
else if (status === 404) code = 'MODEL_UNAVAILABLE';
else if ([408, 425].includes(status)) code = 'REQUEST_TIMEOUT';
else if ([500, 502, 503, 504].includes(status)) code = 'UPSTREAM_UNAVAILABLE';
else if (!status) code = 'NETWORK_ERROR';
else if (status >= 200 && status < 300) code = 'INVALID_RESPONSE';

// Não devolve tokens Bearer nem mensagens ilimitadas nos dados do fluxo.
const diagnostic = String(
  providerError?.message ?? body?.message ?? 'A Cloudflare retornou um erro sem diagnóstico.'
)
  .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, 'Bearer [REDACTED]')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 300);

// Falhas de credencial, cota, rede e indisponibilidade podem tentar outra API.
const retryableStatuses = [401, 403, 408, 425, 429, 500, 502, 503, 504];
const retryable = !status || retryableStatuses.includes(status);
const attempt = Number(context._core?.tentativa ?? 1);
const maxAttempts = Number(context._core?.max_tentativas ?? 3);
const mayRetry = retryable && attempt < maxAttempts;

return [{
  json: {
    _route: mayRetry ? 'retry' : 'error',
    contexto: context,
    code,
    provider_code: providerCode || null,
    diagnostic,
    status_code: status || null,
    freeze_api: [401, 403, 429].includes(status),
    retry_delay_seconds: mayRetry ? 11 : null,
    exhausted: retryable && !mayRetry,
  },
}];

const item = $input.first().json;
const context = item.contexto;
if (!context || !context._core) {
  throw new Error('CORE Cloudflare: contexto de tentativa ausente.');
}
const nextAttempt = Number(context._core.tentativa ?? 1) + 1;
const maxAttempts = Number(context._core.max_tentativas ?? 3);
if (nextAttempt > maxAttempts) {
  throw new Error('CORE Cloudflare: limite de tentativas excedido.');
}
return [{
  json: {
    _route: 'request',
    contexto: {
      ...context,
      _core: { ...context._core, tentativa: nextAttempt }
    }
  }
}];

const item = $input.first().json;
const status = item.status_code == null ? 'indisponível' : String(item.status_code);
const detail = item.diagnostic ? ' — ' + item.diagnostic : '';
throw new Error('CORE Cloudflare: ' + (item.code ?? 'INVALID_INPUT') + ' (HTTP ' + status + ')' + detail + '.');

// Localiza o registro retornado pela procedure, inclusive quando o
// resultado do MySQL vem como arrays ou objetos aninhados.
function encontrarRegistro(valor, profundidade = 0) {
  if (profundidade > 6 || valor == null || typeof valor !== 'object') {
    return null;
  }

  if (!Array.isArray(valor) && 'dsc_api_key' in valor) {
    return valor;
  }

  for (const item of Object.values(valor)) {
    const registro = encontrarRegistro(item, profundidade + 1);
    if (registro) return registro;
  }

  return null;
}

const itensSP = $input.all();
const api = encontrarRegistro(itensSP.map(item => item.json));

if (!api || api.id == null) {
  throw new Error('CORE Cloudflare: nenhuma conta disponível na SP.');
}

// Neste cadastro, confirmar que:
// dsc_api_key    = Account ID
// dsc_api_secret = API Token
const accountId = String(api.dsc_api_key ?? '').trim();
const apiToken = String(api.dsc_api_secret ?? '').trim();

if (!/^[a-f0-9]{32}$/i.test(accountId)) {
  throw new Error(
    'CORE Cloudflare: Account ID ausente ou inválido no campo dsc_api_key.'
  );
}

if (!apiToken) {
  throw new Error(
    'CORE Cloudflare: API Token ausente no campo dsc_api_secret.'
  );
}

// Preserva a tentativa atual quando a execução retorna pelo retry.
let contexto = $('Validar e Preparar').first().json.contexto;

try {
  const retry = $('Incrementar Tentativa').last().json.contexto;
  if (retry) contexto = retry;
} catch {
  // Primeira tentativa: o node de retry ainda não foi executado.
}

return [
  {
    json: {
      _route: 'request',
      contexto: {
        ...contexto,
        account_id: accountId,
        api_id: api.id,
        api_token: apiToken
      }
    }
  }
];

// Valida o identificador numérico da API selecionada antes do UPDATE.
const item = $input.first().json;
const id = Number(item.contexto?.api_id);
if (!Number.isSafeInteger(id) || id <= 0) {
  throw new Error('CORE Cloudflare: api_id inválido; não foi possível congelar a chave.');
}
const query = "UPDATE Config_API_IA SET dth_bloqueio_ate = DATE_ADD(DATE_SUB(UTC_TIMESTAMP(), INTERVAL 3 HOUR), INTERVAL 1 HOUR), dsc_status = 'Bloqueada por erro Workers AI' WHERE id = " + id;
return [{ json: { ...item, _freeze_api_id: id, _freeze_query: query } }];

// A consulta MySQL substitui o item de entrada; restaura o erro interpretado.
const item = $('Preparar Congelamento').last().json;
return [{ json: item }];
